        perspective.setTranslateZ(-150);
        
        
        
        Shape3D cube = new Box(50, 50, 50);
        cube.setCullFace(CullFace.NONE);
        cube.setMaterial(new PhongMaterial(Color.CORAL));

        var toggleGroup = new ToggleGroup();
